'use strict';

// MAIN //

/**
* Serializes an unsigned 64-bit integer as a string.
*
* @private
* @param {number} base - radix
* @returns {string} serialized unsigned 64-bit integer
*/
function toString( base ) { // eslint-disable-line stdlib/no-redeclare
	// eslint-disable-next-line no-undefined
	if ( base === undefined ) {
		base = 10;
	}
	if ( typeof this.value === 'bigint' ) {
		return this.value.toString( base );
	}

	// TODO: implement double word base conversion
	return '?';
}


// EXPORTS //

module.exports = toString;
